# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: `ToolCallLog`, an agent capability that logs each tool call as one timed 'tool'
# record (name, arguments, what it gave back to the AI) and tags every record made during
# it (start.gg requests, HTTP fetches) with the call's `tool_call_id`, so an app can link
# those records back to the call (eg its chat row).
# Usage: Agent(..., capabilities=[ToolCallLog(), ...]) (ds.ai.agent does). Records are off
# until an app turns them on (ds.util.logging.enable_call_logs).
# ---------------------------------------------------------------------------
from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

from pydantic_ai import ToolReturn
from pydantic_ai.capabilities import AbstractCapability
from pydantic_core import to_json

from ds.util.logging import log_call, logger

if TYPE_CHECKING:
    from pydantic_ai import RunContext
    from pydantic_ai.capabilities.abstract import ValidatedToolArgs, WrapToolExecuteHandler
    from pydantic_ai.messages import ToolCallPart
    from pydantic_ai.tools import ToolDefinition

MAX_ARGS_CHARS = 300  # tool arguments kept in the record
# what the tool gave back, kept in the record: cut here so a big table can't fill an app's log
MAX_RESPONSE_CHARS = 4000


def response_text(result: Any) -> str:
    """What a tool gave back to the AI, as text for the log: a string as is, anything else as
    the JSON the model is sent (a value JSON can't hold: its str()), cut to MAX_RESPONSE_CHARS.
    """
    value = result.return_value if isinstance(result, ToolReturn) else result
    if isinstance(value, str):
        text = value
    else:
        try:
            text = to_json(value, indent=2, fallback=str).decode()
        except Exception:  # noqa: BLE001  # logging must never break the tool call
            text = repr(value)
    return text if len(text) <= MAX_RESPONSE_CHARS else text[:MAX_RESPONSE_CHARS] + "…"


@dataclass
class ToolCallLog(AbstractCapability[Any]):
    """One 'tool' record per tool call (name, arguments, response, time, error)

    Also puts `tool_call_id` on every record made while the tool runs (contextvars follow the
    tool into its worker thread).
    """

    async def wrap_tool_execute(  # pydantic-ai's hook signature
        self,
        ctx: RunContext[Any],  # noqa: ARG002  # part of the hook's signature
        *,
        call: ToolCallPart,
        tool_def: ToolDefinition,  # noqa: ARG002
        args: ValidatedToolArgs,
        handler: WrapToolExecuteHandler,
    ) -> Any:
        """Run the tool inside a 'tool' record, with its call id in the log context"""
        arguments = call.args_as_json_str()
        if len(arguments) > MAX_ARGS_CHARS:
            arguments = arguments[:MAX_ARGS_CHARS] + "…"
        with (
            logger.contextualize(tool_call_id=call.tool_call_id),
            log_call("tool", "smash-agent", name=call.tool_name, args=arguments) as record,
        ):
            result = await handler(args)
            record["response"] = response_text(result)
            return result
